const libraryTopics = libraryBriefRows.map(([topic,slug,rows])=>({topic,slug,briefs:rows.trim().split('\n').map(row=>{
 const [title,subtitle,visual,detailText,cta] = row.split('|');
 return {title,subtitle,kicker:topic.toUpperCase(),details:detailText.split(';'),cta,visual,
  tags:[...new Set([topic.toLowerCase(),visual,title.toLowerCase(),subtitle.toLowerCase()])]};
})}));
